-- Mono palette from the handoff; the accent comes from the wallpaper (lua/accent.lua, generated by matugen).
local ok, accent = pcall(require, "accent")
if not ok then accent = "#f2545b" end

local p = {
    bg = "#111111", surface = "#171717", line = "#262626", faint = "#5c5c5c",
    dim = "#8a8a8a", soft = "#bdbdbd", fg = "#efefef", accent = accent,
}

-- Mix two hex colors; t = 0 gives a, t = 1 gives b.
local function blend(a, b, t)
    local function ch(hex, i) return tonumber(hex:sub(i, i + 1), 16) end
    local out = "#"
    for i = 2, 6, 2 do
        out = out .. string.format("%02x", math.floor(ch(a, i) * (1 - t) + ch(b, i) * t + 0.5))
    end
    return out
end

local function to_hsl(hex)
    local r, g, b = tonumber(hex:sub(2, 3), 16) / 255, tonumber(hex:sub(4, 5), 16) / 255, tonumber(hex:sub(6, 7), 16) / 255
    local max, min = math.max(r, g, b), math.min(r, g, b)
    local l, h, s = (max + min) / 2, 0, 0
    if max ~= min then
        local d = max - min
        s = l > 0.5 and d / (2 - max - min) or d / (max + min)
        if max == r then h = (g - b) / d % 6 elseif max == g then h = (b - r) / d + 2 else h = (r - g) / d + 4 end
        h = h * 60
    end
    return h, s, l
end

local function from_hsl(h, s, l)
    h = h % 360
    local c = (1 - math.abs(2 * l - 1)) * s
    local x = c * (1 - math.abs((h / 60) % 2 - 1))
    local m = l - c / 2
    local rr, gg, bb
    if h < 60 then rr, gg, bb = c, x, 0 elseif h < 120 then rr, gg, bb = x, c, 0
    elseif h < 180 then rr, gg, bb = 0, c, x elseif h < 240 then rr, gg, bb = 0, x, c
    elseif h < 300 then rr, gg, bb = x, 0, c else rr, gg, bb = c, 0, x end
    return string.format("#%02x%02x%02x", math.floor((rr + m) * 255 + 0.5), math.floor((gg + m) * 255 + 0.5), math.floor((bb + m) * 255 + 0.5))
end

-- Rotate a hex color's hue by deg degrees, keeping saturation and lightness.
local function rotate_hue(hex, deg)
    local h, s, l = to_hsl(hex)
    return from_hsl(h + deg, s, l)
end

-- Extra tones so syntax isn't just white-or-accent, all derived from the wallpaper accent.
p.pastel      = blend(p.accent, p.fg, 0.55)    -- constants, numbers
-- The raw complement is as saturated as the accent and fights it, so pull it toward gray.
p.secondary   = blend(rotate_hue(p.accent, 180), p.dim, 0.45) -- complement: types, constructors
p.sec_pastel  = blend(p.secondary, p.soft, 0.5)               -- strings

-- Re-map the borrowed colors around the accent. Each tokyonight hue family snaps to its own
-- slot (degrees from the accent hue); lightness and saturation are kept, so contrast is too.
-- `keep` is how much of the family's internal hue variation survives.
local syntax_tint = {
    keep = 0.3,
    slots = {
        { from = 221, to = 0 },   -- blue: functions, types        -> accent
        { from = 197, to = -15 }, -- cyan: operators, specials     -> just off accent
        { from = 170, to = -28 }, -- teal: members, properties
        { from = 263, to = -35 }, -- purple: keywords (for, if, in)
        { from = 84,  to = -95 }, -- green: strings
        { from = 313, to = 95 },  -- pink: def, return, with
        { from = 355, to = 20 },  -- red: self, builtin variables
        { from = 30,  to = 180 }, -- orange/yellow: parameters, constants -> complement
    },
}

-- Groups that skip the remap and get a fixed color instead.
local ah = to_hsl(p.accent)
local syntax_fixed = {
    ["@variable"]        = from_hsl(ah - 120, 0.65, 0.78), -- plain variables: purple
    ["@function"]             = p.accent,                -- functions: the accent itself
    ["@function.call"]        = p.accent,
    ["@function.method"]      = p.accent,
    ["@function.method.call"] = p.accent,
    ["Function"]              = p.accent,
    ["@string"]          = p.dim,                        -- strings: quiet gray
    ["String"]           = p.dim,
}

local function tint(int)
    local h, s, l = to_hsl(string.format("#%06x", int))
    if s < 0.08 then return int end
    local function dist(x, y) return (x - y + 180) % 360 - 180 end
    local best
    for _, slot in ipairs(syntax_tint.slots) do
        if not best or math.abs(dist(h, slot.from)) < math.abs(dist(h, best.from)) then best = slot end
    end
    return tonumber(from_hsl(ah + best.to + dist(h, best.from) * syntax_tint.keep, s, l):sub(2), 16)
end
local syntax_groups = {}
for _, g in ipairs({
    "Comment", "Constant", "String", "Character", "Number", "Boolean", "Float", "Identifier",
    "Function", "Statement", "Conditional", "Repeat", "Label", "Operator", "Keyword", "Exception",
    "PreProc", "Include", "Define", "Macro", "PreCondit", "Type", "StorageClass", "Structure",
    "Typedef", "Special", "SpecialChar", "Tag", "Delimiter", "SpecialComment", "Debug", "Todo",
}) do syntax_groups[g] = true end

local M = { p = p }

-- Our UI colors plus a choice of code colors. opts:
--   name        colorscheme name to report (g:colors_name)
--   syntax_from borrow code colors from this scheme; nil = our own mono+accent syntax
--   tint        re-map the borrowed colors around the accent (syntax_tint / syntax_fixed)
function M.apply(opts)
    local syntax_from = opts.syntax_from
    local syntax_tint = opts.tint and syntax_tint or nil
    -- Grab the borrowed scheme's syntax colors first so they can be put back over ours.
    local stock
    if syntax_from then
        vim.cmd.colorscheme(syntax_from)
        stock = {}
        for name in pairs(vim.api.nvim_get_hl(0, {})) do
            if name:sub(1, 1) == "@" or syntax_groups[name] then
                local val = vim.api.nvim_get_hl(0, { name = name, link = true })
                if syntax_tint and val.fg then val.fg = tint(val.fg) end
                if syntax_tint and val.sp then val.sp = tint(val.sp) end
                if syntax_tint and syntax_fixed[name] then
                    val = { fg = syntax_fixed[name], italic = val.italic, bold = val.bold }
                end
                stock[name] = val
            end
        end
    end

    require("mini.base16").setup({
        palette = {
            base00 = p.bg,     base01 = p.surface, base02 = p.line,   base03 = p.faint,
            base04 = p.dim,    base05 = p.fg,      base06 = "#f5f5f5", base07 = "#ffffff",
            base08 = p.accent, base09 = p.fg,      base0A = p.fg,     base0B = p.accent,
            base0C = p.soft,   base0D = p.fg,      base0E = p.soft,   base0F = p.dim,
        },
        use_cterm = true,
    })
    -- Let kitty's background show through, keywords bold white.
    local hl = function(name, val) vim.api.nvim_set_hl(0, name, val) end
    hl("Normal",       { fg = p.fg, bg = "NONE" })
    hl("NormalNC",     { fg = p.fg, bg = "NONE" })
    hl("NormalFloat",  { fg = p.fg, bg = "NONE" })
    hl("FloatBorder",  { fg = p.line, bg = "NONE" })
    hl("SignColumn",   { bg = "NONE" })
    hl("LineNr",       { fg = p.faint, bg = "NONE" })
    hl("CursorLineNr", { fg = p.accent, bg = "NONE", bold = true })
    hl("CursorLine",   { bg = p.surface })
    hl("WinSeparator", { fg = p.line, bg = "NONE" })
    hl("Keyword",      { fg = p.fg, bold = true })
    hl("Statement",    { fg = p.fg, bold = true })
    hl("@keyword",     { fg = p.fg, bold = true })
    hl("Comment",      { fg = p.faint, italic = true })

    -- Syntax: grays carry structure, the accent family carries meaning.
    -- keywords fg bold · functions accent · constants pastel
    -- types secondary · strings secondary pastel · members soft · punctuation dim
    hl("Identifier",           { fg = p.fg })
    hl("@variable",            { fg = p.fg })
    hl("@variable.parameter",  { fg = p.soft, italic = true })
    hl("@variable.builtin",    { fg = p.soft, italic = true })
    hl("@variable.member",     { fg = p.soft })
    hl("@property",            { fg = p.soft })
    hl("Function",             { fg = p.accent })
    hl("@function",            { fg = p.accent })
    hl("@function.call",       { fg = p.accent })
    hl("@function.method",     { fg = p.accent })
    hl("@function.method.call",{ fg = p.accent })
    hl("@function.builtin",    { fg = p.accent, italic = true })
    hl("@constructor",         { fg = p.secondary })
    hl("String",               { fg = p.sec_pastel })
    hl("@string",              { fg = p.sec_pastel })
    hl("@string.documentation",{ fg = p.faint, italic = true })
    hl("@string.escape",       { fg = p.secondary })
    hl("@string.regexp",       { fg = p.secondary })
    hl("Constant",             { fg = p.pastel })
    hl("@constant",            { fg = p.pastel })
    hl("@constant.builtin",    { fg = p.pastel, italic = true })
    hl("Number",               { fg = p.pastel })
    hl("Boolean",              { fg = p.pastel })
    hl("Special",              { fg = p.pastel })
    hl("Type",                 { fg = p.secondary })
    hl("@type",                { fg = p.secondary })
    hl("@type.builtin",        { fg = p.secondary, italic = true })
    hl("@module",              { fg = p.soft })
    hl("PreProc",              { fg = p.soft })
    hl("Include",              { fg = p.fg, bold = true })
    hl("@attribute",           { fg = p.pastel })
    hl("Operator",             { fg = p.dim })
    hl("@operator",            { fg = p.dim })
    hl("Delimiter",            { fg = p.dim })
    hl("@punctuation",         { fg = p.dim })
    hl("@punctuation.bracket", { fg = p.dim })
    hl("@punctuation.delimiter",{ fg = p.dim })
    hl("@tag",                 { fg = p.accent })
    hl("@tag.attribute",       { fg = p.soft })
    hl("@tag.delimiter",       { fg = p.dim })
    -- Markdown
    hl("@markup.heading",      { fg = p.accent, bold = true })
    hl("@markup.link",         { fg = p.secondary, underline = true })
    hl("@markup.raw",          { fg = p.sec_pastel })
    hl("NeoTreeNormal",   { bg = "NONE" })
    hl("NeoTreeNormalNC", { bg = "NONE" })

    if stock then
        -- Clear every syntax group we or base16 set, then restore the borrowed ones.
        for name in pairs(vim.api.nvim_get_hl(0, {})) do
            if name:sub(1, 1) == "@" or syntax_groups[name] then hl(name, stock[name] or {}) end
        end
    end
    vim.g.colors_name = opts.name
end

return M
